#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Peli on a real iPhone and iPad through SideStore (ios/README.md, "On a real
# device"). Steps follow docs.sidestore.io as of 2026-11-17: iloader installs
# SideStore and its pairing file, LocalDevVPN must be on to install or
# refresh. Your Apple ID goes into iloader and SideStore only, never here.
# Saves the device identifiers and Peli's bundle ids (SideStore adds your team
# id) to bin/ios/devices.env, which is git-ignored.

cd "$(dirname "$0")/../../.."
ENV_FILE=bin/ios/devices.env
mkdir -p bin/ios
IPA=bin/ios/peli.ipa
ICLOUD="$HOME/Library/Mobile Documents/com~apple~CloudDocs/Peli"

DEVICES=(iPhone iPad)
TOTAL_STAGES=$((2 + 8 * ${#DEVICES[@]}))

# physical_devices prints "identifier  type  name  pairing" for each real
# device devicectl can see.
physical_devices() {
  local tmp; tmp=$(mktemp)
  xcrun devicectl list devices --json-output "$tmp" >/dev/null 2>&1 || { rm -f "$tmp"; return 0; }
  python3 -I - "$tmp" <<'PY'
import json, sys
d = json.load(open(sys.argv[1]))
for dev in d.get("result", {}).get("devices", []):
    hw = dev.get("hardwareProperties", {})
    if hw.get("reality") != "physical":
        continue
    print("  %s  %s  %s  %s" % (dev.get("identifier"), hw.get("deviceType", "?"),
          dev.get("deviceProperties", {}).get("name", "?"),
          dev.get("connectionProperties", {}).get("pairingState", "?")))
PY
  rm -f "$tmp"
}

# peli_bundle_id DEVICE prints the bundle id Peli is installed under, if any.
peli_bundle_id() {
  local tmp; tmp=$(mktemp)
  xcrun devicectl device info apps --device "$1" --json-output "$tmp" >/dev/null 2>&1 || { rm -f "$tmp"; return 0; }
  python3 -I - "$tmp" <<'PY'
import json, sys
apps = json.load(open(sys.argv[1])).get("result", {}).get("apps", [])
print(next((a["bundleIdentifier"] for a in apps if a.get("bundleIdentifier", "").startswith("k22i.net.peli")), ""))
PY
  rm -f "$tmp"
}

banner "Peli on iPhone and iPad with SideStore"

# ── Mac, once ─────────────────────────────────────────────────────────────
stage "Before you start"
say "You need, for each device: a passcode set, the same Wi-Fi as this Mac"
say "(SideStore can't install or refresh on mobile data), and a USB cable."
say "Two devices on one free Apple ID use: SideStore + Peli = 2 of the 3 app"
say "slots on EACH device, and 2 of the 10 App IDs a week on the account."
if [[ -f "$IPA" ]]; then
  note "Found $IPA (build $(unzip -p "$IPA" Payload/peli.app/Info.plist | plutil -extract CFBundleVersion raw -o - - 2>/dev/null || echo '?'))."
else
  warn "No $IPA yet. In another terminal: wails3 task ios:sideload"
  pause "Press Enter once it has finished"
fi
pause

stage "Install iloader on this Mac"
say "iloader is the installer SideStore's docs name for macOS: it installs"
say "SideStore over the cable and places its pairing file."
if [[ -d /Applications/iloader.app ]]; then
  note "iloader is already in /Applications."
else
  open_url "https://iloader.app"
  step "Download the macOS (universal) DMG, open it, drag iloader to Applications."
  step "Open iloader once from Applications (allow it if macOS asks)."
fi
pause "Press Enter when iloader opens"

# ── Each device ───────────────────────────────────────────────────────────
for DEV in "${DEVICES[@]}"; do
  KEY=$(printf '%s' "$DEV" | tr '[:lower:]' '[:upper:]')

  stage "$DEV: LocalDevVPN"
  say "SideStore talks to the device's own services through a loopback VPN."
  say "It has to be connected whenever SideStore installs or refreshes."
  step "On the $DEV: App Store → search \"LocalDevVPN\" → Get."
  note "(Listing: https://apps.apple.com/app/localdevvpn/id6755608044)"
  step "Open LocalDevVPN → Connect → Allow VPN Configurations → passcode."
  note "Remove WireGuard/StosVPN profiles if you had them; SideStore's docs say they fail."
  pause "Press Enter when the VPN shows Connected"

  stage "$DEV: install SideStore with iloader"
  step "Plug the $DEV into this Mac. On the $DEV tap Trust and enter the passcode."
  step "In iloader, sign in with your Apple ID (case-sensitive; it needn't be the"
  say  "  device's own Apple ID). This is the account SideStore signs Peli with."
  step "Select the $DEV in the list → 'Install SideStore (Stable)'. Wait for it."
  note "If iloader offers to update itself, say Yes."
  pause "Press Enter when iloader says SideStore is installed"

  stage "$DEV: trust the developer and turn on Developer Mode"
  step "Settings → General → VPN & Device Management → Developer App →"
  say  "  your Apple ID → Trust \"…\" → Trust."
  step "Settings → Privacy & Security → (bottom) Developer Mode → on → Restart."
  step "After the restart, unlock and confirm 'Turn On' with the passcode."
  note "Developer Mode is also what lets Xcode's devicectl read Peli's logs."
  pause "Press Enter when the $DEV is back on the Home Screen"

  stage "$DEV: finish SideStore's setup"
  step "Wi-Fi on and LocalDevVPN Connected, then open SideStore."
  step "Sign in with the same Apple ID you used in iloader."
  step "My Apps → tap the '7 DAYS' button next to SideStore."
  if [[ "$DEV" != "${DEVICES[0]}" ]]; then
    warn "If SideStore asks to revoke certificates, DON'T revoke the one named"
    warn "\"SideStore - …'s ${DEVICES[0]}\": the ${DEVICES[0]}'s apps would stop opening."
    say  "  Keep existing, or revoke only certificates nothing uses any more."
  else
    step "If it asks to revoke or create a signing certificate: Yes / Refresh Now."
  fi
  say "SideStore jumps to the Home Screen with a notification, then comes back."
  note "Errors about AFC, 1006 or no connection later on: iloader → Manage Pairing File"
  note "→ Place next to SideStore (the pairing file can expire after iOS updates)."
  pause "Press Enter when SideStore shows 7 DAYS"

  stage "$DEV: install Peli"
  if [[ -f "$IPA" ]]; then
    mkdir -p "$ICLOUD" && cp -f "$IPA" "$ICLOUD/peli.ipa"
    note "Copied $IPA to iCloud Drive/Peli/peli.ipa."
  fi
  step "On the $DEV: Files → iCloud Drive → Peli → tap peli.ipa's cloud icon so it"
  say  "  downloads (wait for the size to show)."
  step "SideStore → My Apps → + (top left) → iCloud Drive → Peli → peli.ipa."
  step "Wait for it to install (it registers one App ID: k22i.net.peli.<team id>)."
  step "Open Peli once: it should reach the Welcome screen."
  pause "Press Enter when Peli has opened"

  stage "$DEV: background refresh"
  say "SideStore refreshes in the background with iOS's background fetch, so"
  say "iOS must allow it, and LocalDevVPN must still be connected when it runs."
  step "Settings → General → Background App Refresh → on, and on for SideStore."
  step "SideStore → Settings → Background Refresh → on."
  note "Low Power Mode pauses background refresh; the Shortcut is the backstop."
  pause

  stage "$DEV: Shortcuts automation"
  say "A daily automation makes sure a refresh happens even if iOS skips the"
  say "background one. Pick a time the $DEV is usually on Wi-Fi (overnight on"
  say "the charger is ideal)."
  step "Shortcuts → Automation → + → Time of Day → e.g. 04:00, Daily."
  step "Choose 'Run Immediately' (leave 'Notify When Run' on for the first week)."
  step "Next → New Blank Automation → Add Action → search \"SideStore\" →"
  say  "  'Refresh All Apps' → Done."
  note "Labels can differ a little between iOS versions."
  step "Test it: open the automation and tap ▶ (with LocalDevVPN connected)."
  say  "  SideStore → My Apps should then show 7 DAYS for SideStore and Peli."
  pause "Press Enter when the test run has refreshed both apps"

  stage "$DEV: connect to Xcode for logs"
  step "Keep the $DEV plugged in and unlocked."
  say "Devices this Mac sees:"
  LIST=$(physical_devices)
  if [[ -z "$LIST" ]]; then
    warn "None yet. Open Xcode → Window → Devices and Simulators, wait for the"
    warn "$DEV to finish 'Preparing', then press Enter to look again."
    pause
    LIST=$(physical_devices)
  fi
  printf '%s\n' "${LIST:-  (still none)}"
  ask "${KEY}_ID" "Paste the $DEV's identifier (first column):"
  ID_VAL=$(eval "printf '%s' \"\${${KEY}_ID}\"")
  if [[ -n "$ID_VAL" ]]; then
    write_env "${KEY}_ID" "$ID_VAL"
    BID=$(peli_bundle_id "$ID_VAL")
    if [[ -n "$BID" ]]; then
      write_env "${KEY}_PELI_BUNDLE_ID" "$BID"
    else
      SKIPPED+=("$DEV: Peli not found through devicectl (is it installed and the device paired?)")
      warn "Couldn't see Peli on the $DEV through devicectl."
    fi
  else
    SKIPPED+=("$DEV: device identifier for logs (xcrun devicectl list devices)")
  fi
  note "Logs from now on: wails3 task ios:device:console DEVICE_ID=<identifier>"
  pause
done

finish
say "Next: the on-device checklist in ios/README.md (\"On a real device\")."
say "Re-run this wizard for a new device, or after a reset or an iOS update."
printf '\n'
